CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, is_admin boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_limits(key text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE clients(id uuid PRIMARY KEY, name text NOT NULL, sector text NOT NULL, organization_type text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', size text NOT NULL DEFAULT '', employee_count integer CHECK(employee_count>=0), sponsor text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(client_id uuid NOT NULL REFERENCES clients, user_id uuid NOT NULL REFERENCES users, role text NOT NULL CHECK(role IN ('lead','consultant','reviewer')), PRIMARY KEY(client_id,user_id));
CREATE TABLE modules(id text PRIMARY KEY, title text NOT NULL);
CREATE TABLE frameworks(id uuid PRIMARY KEY, module_id text NOT NULL REFERENCES modules, version text NOT NULL, status text NOT NULL CHECK(status IN ('Draft','Approved')), definition jsonb NOT NULL, approved_by uuid REFERENCES users, approved_at timestamptz, UNIQUE(module_id,version));
CREATE TABLE client_modules(client_id uuid NOT NULL REFERENCES clients, module_id text NOT NULL REFERENCES modules, enabled boolean NOT NULL DEFAULT true, PRIMARY KEY(client_id,module_id));
CREATE TABLE assessments(id uuid PRIMARY KEY, client_id uuid NOT NULL REFERENCES clients, title text NOT NULL, assessment_date date NOT NULL, assessor_id uuid NOT NULL REFERENCES users, participants text NOT NULL DEFAULT '', assessment_type text NOT NULL DEFAULT 'Consultant-led', status text NOT NULL DEFAULT 'Draft', revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,client_id), CHECK(status IN ('Draft','Data Collection','Assessment in Progress','Evidence Review','Calibration','Management Review','Approved','Closed')));
CREATE TABLE assessment_modules(assessment_id uuid NOT NULL REFERENCES assessments, framework_id uuid NOT NULL REFERENCES frameworks, weight numeric NOT NULL CHECK(weight>0), PRIMARY KEY(assessment_id,framework_id));
CREATE TABLE responses(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, criterion_id text NOT NULL, answers jsonb NOT NULL DEFAULT '{}', consultant_score numeric CHECK(consultant_score BETWEEN 1 AND 5), reviewer_score numeric CHECK(reviewer_score BETWEEN 1 AND 5), target numeric CHECK(target BETWEEN 1 AND 5), target_rationale text NOT NULL DEFAULT '', comment text NOT NULL DEFAULT '', internal_notes text NOT NULL DEFAULT '', confidence text CHECK(confidence IN ('Low','Medium','High')), confidence_rationale text NOT NULL DEFAULT '', review_status text NOT NULL DEFAULT 'Pending' CHECK(review_status IN ('Pending','Returned','Approved')), review_rationale text NOT NULL DEFAULT '', reviewed_by uuid REFERENCES users, revision integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assessment_id,criterion_id), UNIQUE(id,assessment_id,client_id), FOREIGN KEY(assessment_id,client_id) REFERENCES assessments(id,client_id));
CREATE TABLE evidence(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, title text NOT NULL, kind text NOT NULL, description text NOT NULL DEFAULT '', source text NOT NULL DEFAULT '', evidence_date date, owner text NOT NULL DEFAULT '', url text, object_key text, mime_type text, byte_size integer, checksum text, verification_status text NOT NULL DEFAULT 'Unverified' CHECK(verification_status IN ('Unverified','Verified','Rejected')), strength text NOT NULL DEFAULT 'Unclassified', reviewer_comments text NOT NULL DEFAULT '', scan_status text NOT NULL DEFAULT 'Not applicable', revision integer NOT NULL DEFAULT 0, created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,assessment_id,client_id), FOREIGN KEY(assessment_id,client_id) REFERENCES assessments(id,client_id));
CREATE TABLE evidence_links(evidence_id uuid NOT NULL, response_id uuid NOT NULL, assessment_id uuid NOT NULL, client_id uuid NOT NULL, PRIMARY KEY(evidence_id,response_id), FOREIGN KEY(evidence_id,assessment_id,client_id) REFERENCES evidence(id,assessment_id,client_id), FOREIGN KEY(response_id,assessment_id,client_id) REFERENCES responses(id,assessment_id,client_id));
CREATE TABLE findings(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, response_id uuid NOT NULL, title text NOT NULL, description text NOT NULL, condition text NOT NULL DEFAULT '', root_cause text NOT NULL DEFAULT '', consequence text NOT NULL DEFAULT '', severity text NOT NULL, priority text NOT NULL, review_status text NOT NULL DEFAULT 'Draft', created_by uuid NOT NULL REFERENCES users, UNIQUE(id,assessment_id,client_id), FOREIGN KEY(assessment_id,client_id) REFERENCES assessments(id,client_id), FOREIGN KEY(response_id,assessment_id,client_id) REFERENCES responses(id,assessment_id,client_id));
CREATE TABLE knowledge(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('KPI','Tool','Template','Case Study','Source')), title text NOT NULL, description text NOT NULL DEFAULT '', source_url text, source_section text NOT NULL DEFAULT '', source_type text NOT NULL DEFAULT 'Internal consulting material', verification_status text NOT NULL DEFAULT 'Draft', verified_at timestamptz, content jsonb NOT NULL DEFAULT '{}');
CREATE TABLE recommendations(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, response_id uuid NOT NULL, finding_id uuid, title text NOT NULL, action text NOT NULL, rationale text NOT NULL, approach text NOT NULL, deliverables text NOT NULL, owner text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'Medium', impact text NOT NULL DEFAULT '', effort text NOT NULL DEFAULT '', horizon text NOT NULL DEFAULT '0-3 months', source_location text NOT NULL, status text NOT NULL DEFAULT 'Draft', approved_by uuid REFERENCES users, UNIQUE(id,assessment_id,client_id), FOREIGN KEY(assessment_id,client_id) REFERENCES assessments(id,client_id), FOREIGN KEY(response_id,assessment_id,client_id) REFERENCES responses(id,assessment_id,client_id), FOREIGN KEY(finding_id,assessment_id,client_id) REFERENCES findings(id,assessment_id,client_id));
CREATE TABLE recommendation_assets(recommendation_id uuid NOT NULL REFERENCES recommendations, knowledge_id uuid NOT NULL REFERENCES knowledge, PRIMARY KEY(recommendation_id,knowledge_id));
CREATE TABLE roadmap(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, recommendation_id uuid NOT NULL, title text NOT NULL, objective text NOT NULL, actions text NOT NULL, deliverable text NOT NULL, owner text NOT NULL, start_month integer NOT NULL CHECK(start_month>=0), end_month integer NOT NULL CHECK(end_month>=start_month), priority text NOT NULL, impact text NOT NULL DEFAULT '', effort text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Not Started', revision integer NOT NULL DEFAULT 0, UNIQUE(id,assessment_id,client_id), FOREIGN KEY(recommendation_id,assessment_id,client_id) REFERENCES recommendations(id,assessment_id,client_id));
CREATE TABLE roadmap_dependencies(initiative_id uuid NOT NULL, dependency_id uuid NOT NULL, assessment_id uuid NOT NULL, client_id uuid NOT NULL, PRIMARY KEY(initiative_id,dependency_id), CHECK(initiative_id<>dependency_id), FOREIGN KEY(initiative_id,assessment_id,client_id) REFERENCES roadmap(id,assessment_id,client_id), FOREIGN KEY(dependency_id,assessment_id,client_id) REFERENCES roadmap(id,assessment_id,client_id));
CREATE TABLE lessons(id uuid PRIMARY KEY, assessment_id uuid NOT NULL, client_id uuid NOT NULL, title text NOT NULL, recurring_gap text NOT NULL, root_cause text NOT NULL, action text NOT NULL, worked text NOT NULL, did_not_work text NOT NULL, outcome text NOT NULL, notes text NOT NULL, reusable boolean NOT NULL DEFAULT false, created_by uuid NOT NULL REFERENCES users, FOREIGN KEY(assessment_id,client_id) REFERENCES assessments(id,client_id));
CREATE TABLE report_snapshots(id uuid PRIMARY KEY, assessment_id uuid NOT NULL REFERENCES assessments, assessment_revision integer NOT NULL, approved_by uuid NOT NULL REFERENCES users, approved_at timestamptz NOT NULL DEFAULT now(), report jsonb NOT NULL, UNIQUE(assessment_id,assessment_revision));
CREATE TABLE audit_events(id uuid PRIMARY KEY, client_id uuid REFERENCES clients, assessment_id uuid REFERENCES assessments, actor_id uuid REFERENCES users, action text NOT NULL, entity_id text NOT NULL, previous_value jsonb, new_value jsonb, reason text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sync_outbox(id uuid PRIMARY KEY, snapshot_id uuid NOT NULL UNIQUE REFERENCES report_snapshots, status text NOT NULL DEFAULT 'Pending', attempts integer NOT NULL DEFAULT 0, last_error text, completed_at timestamptz);
CREATE INDEX responses_assessment ON responses(assessment_id);
CREATE INDEX evidence_assessment ON evidence(assessment_id);
CREATE INDEX audit_assessment ON audit_events(assessment_id,occurred_at);
CREATE FUNCTION protect_approved_framework() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='Approved' THEN RAISE EXCEPTION 'Published frameworks are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_framework BEFORE UPDATE OR DELETE ON frameworks FOR EACH ROW EXECUTE FUNCTION protect_approved_framework();
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_report BEFORE UPDATE OR DELETE ON report_snapshots FOR EACH ROW EXECUTE FUNCTION reject_mutation();
INSERT INTO schema_versions(version) VALUES(1);
